118	                        [attr.aria-label]="'Take statement for ' + p.name">Statement</button>
119	                @if (personError()?.id === p.id) {
120	                  <p role="alert" class="error" data-testid="person-error">{{ personError()?.message }}</p>
121	                }
122	              </td>
123	              <td>
124	                <span data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</span>
125	                <span>from <span data-testid="person-retired-from">{{ p.retiredFrom ?? '' }}</span></span>
126	                <label [for]="'person-retire-date-' + p.id" class="visually-hidden">Retire {{ p.name }} from</label>
127	                <input type="date" [id]="'person-retire-date-' + p.id" data-testid="person-retire-date"
128	                       #retireDate (input)="clearPersonError(p.id)" />
129	                <button type="button" data-testid="person-retire" (click)="retire(p, retireDate.value)"
130	                        [attr.aria-label]="'Retire ' + p.name">Retire</button>
131	              </td>
132	              <td>
133	                <span data-testid="person-hold">{{ p.held ? 'yes' : 'no' }}</span>
134	                <button type="button" data-testid="person-hold-toggle" (click)="toggleHold(p)"
135	                        [attr.aria-label]="(p.held ? 'Release ' : 'Hold ') + p.name">{{ p.held ? 'Release' : 'Hold' }}</button>
136	              </td>
137	              <td>
138	                <span data-testid="person-overdue-count">{{ overdueOf(p).count }}</span>
139	                <span>Total <span data-testid="person-overdue-total">{{ money(overdueOf(p).cents) }}</span></span>
140	              </td>
141	              <td>
142	                <app-claims [personId]="p.id" [personName]="p.name" [claims]="claimsOf(p.id)" [rates]="ratesOf(p.grade)"
143	                            [periods]="periods()"
144	                            (saved)="claimSaved($event)" />
145	              </td>
146	              <td>
147	                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)"
148	                        [attr.aria-label]="'Edit ' + p.name">Edit</button>
149	              </td>
150	            </tr>
151	          }
152	        </tbody>
153	      </table>
154	      <p>Claimed total: <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
155	      <p>Due total: <strong data-testid="rollup-due-total">{{ dueTotal() }}</strong></p>
156	      <p>Overdue: <strong data-testid="rollup-overdue-count">{{ overdueTotal().count }}</strong>
157	        totalling <strong data-testid="rollup-overdue-total">{{ money(overdueTotal().cents) }}</strong></p>
158	    </section>
159	  `,
160	})
161	export class People {
162	  private readonly http = inject(HttpClient);
163	  protected readonly session = inject(Session);
164	
165	  protected readonly grades = GRADES;
166	  protected readonly people = signal<Person[]>([]);
167	  /** The people on screen: everyone, less the retired unless show retired is on. */
168	  protected readonly listed = computed(() =>
169	    this.session.showRetired() ? this.people() : this.people().filter((p) => !p.retired),
170	  );
171	  /** Every claim on the sheet, newest first. */
172	  protected readonly claims = signal<Claim[]>([]);
173	  private readonly claimsByPerson = computed(() => {
174	    const by = new Map<number, Claim[]>();
175	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
176	    return by;
177	  });
178	  /** The ids of the people on hold. */
179	  private readonly heldIds = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
180	  /** Whether the claim counts in the live totals: OPEN or SETTLED, and not OPEN for a held person. */
181	  private readonly counts = (c: Claim): boolean => countsFor(c, this.heldIds().has(c.personId));
182	  protected readonly claimedTotal = computed(() => money(this.claims().filter(this.counts).reduce((sum, c) => sum + cents(c.amount), 0)));
183	  /** The sheet's rates, each for a grade from its from-date. */
184	  protected readonly rates = signal<Rate[]>([]);
185	  /** The sheet's periods, earliest first. */
186	  protected readonly periods = signal<Period[]>([]);
187	  /** Each period's due-total in cents, by id: the dues of the claims that count whose date falls in it. */
188	  private readonly periodDueCents = computed(() => {
189	    const grades = new Map(this.people().map((p) => [p.id, p.grade]));
190	    const by = new Map<number, number>();
191	    for (const c of this.claims().filter(this.counts)) {
192	      const period = periodOn(this.periods(), c.date);
193	      const grade = grades.get(c.personId);
194	      if (period === null || grade === undefined) continue;
195	      by.set(period.id, (by.get(period.id) ?? 0) + (claimDueCents(c, this.ratesOf(grade), cents(this.session.floor()), this.session.late()) ?? 0));
196	    }
197	    return by;
198	  });
199	  protected readonly periodDueTotalOf = (p: Period): string => money(this.periodDueCents().get(p.id) ?? 0);
200	  /** Each person's statements, for those who have had any. */
201	  protected readonly statements = signal<StatementSummary[]>([]);
202	  private readonly statementByPerson = computed(() => new Map(this.statements().map((s) => [s.personId, s])));
203	  /** The error from the last action on a person's row, if it was refused. */
204	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
205	  private readonly ratesByGrade = computed(() => {
206	    const by = new Map<string, Rate[]>();
207	    for (const r of this.rates()) by.set(r.grade, [...(by.get(r.grade) ?? []), r]);
208	    return by;
209	  });
210	  /** Each grade's rate in force on the sheet's today, for the grades that have one. */
211	  private readonly pctByGrade = computed(() => {
212	    const today = this.session.today();
213	    const by = new Map<string, string>();
214	    if (today === null) return by;
215	    for (const [grade, rates] of this.ratesByGrade()) {
216	      const pct = pctOn(rates, today);
217	      if (pct !== null) by.set(grade, pct);
218	    }
219	    return by;
220	  });
221	  /** Everyone's due-total added up, skipping those whose due-total is n/a. */
222	  protected readonly dueTotal = computed(() =>
223	    money(this.people().reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0)),
224	  );
225	  /** Each person's overdue claims that count, by id: how many and their dues in cents. */
226	  private readonly overdueByPerson = computed(() => {
227	    const terms = this.session.terms();
228	    const today = this.session.today();
229	    const floor = cents(this.session.floor());
230	    const late = this.session.late();
231	    const by = new Map<number, Overdue>();
232	    for (const p of this.people()) {
233	      const rates = this.ratesOf(p.grade);
234	      const overdue = this.claimsOf(p.id).filter((c) => this.counts(c) && isOverdue(c, terms, today));
235	      by.set(p.id, { count: overdue.length, cents: overdue.reduce((sum, c) => sum + (claimDueCents(c, rates, floor, late) ?? 0), 0) });
236	    }
237	    return by;
238	  });
239	  /** The sheet's overdue claims that count: everyone's added up. */
240	  protected readonly overdueTotal = computed(() => {
241	    let total: Overdue = { count: 0, cents: 0 };
242	    for (const o of this.overdueByPerson().values()) total = { count: total.count + o.count, cents: total.cents + o.cents };
243	    return total;
244	  });
245	  protected readonly money = money;
246	  protected readonly editingId = signal<number | null>(null);
247	  /** The version of the person being edited, as the form loaded it. */
248	  private editingVersion = 0;
249	  /** A submit is under way; another one waits for its answer rather than storing twice. */
250	  private saving = false;
251	  protected readonly error = signal('');
252	  protected readonly form = new FormGroup({
253	    name: new FormControl('', { nonNullable: true }),
254	    grade: new FormControl('A', { nonNullable: true }),
255	  });
256	
257	  /** A quick-add is under way; another one waits for its answer rather than storing twice. */
258	  private quickAdding = false;
259	  protected readonly quickError = signal('');
260	  protected readonly quickForm = new FormGroup({
261	    name: new FormControl('', { nonNullable: true }),
262	    amount: new FormControl('', { nonNullable: true }),
263	  });
264	
265	  constructor() {
266	    this.form.valueChanges.subscribe(() => this.error.set(''));
267	    this.quickForm.valueChanges.subscribe(() => this.quickError.set(''));
268	    effect(() => {
269	      const id = this.session.sheetId();
270	      this.session.loads();
271	      this.people.set([]);
272	      this.claims.set([]);
273	      this.rates.set([]);
274	      this.periods.set([]);
275	      this.statements.set([]);
276	      this.personError.set(null);
277	      this.reset();
278	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
279	      this.quickError.set('');
280	      if (id) void this.load(id);
281	    });
282	  }
283	
284	  private headers(): Record<string, string> {
285	    return { 'X-User': this.session.user() ?? '' };
286	  }
287	
288	  private url(sheet: string): string {
289	    return `/api/sheets/${encodeURIComponent(sheet)}/people`;
290	  }
291	
292	  private async load(sheet: string): Promise<void> {
293	    try {
294	      const [list, claims, rates, statements, periods] = await Promise.all([
295	        firstValueFrom(this.http.get<Person[]>(this.url(sheet), { headers: this.headers() })),
296	        firstValueFrom(this.http.get<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`, { headers: this.headers() })),
297	        firstValueFrom(this.http.get<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`, { headers: this.headers() })),
298	        firstValueFrom(this.http.get<StatementSummary[]>(`/api/sheets/${encodeURIComponent(sheet)}/statements`, { headers: this.headers() })),
299	        firstValueFrom(this.http.get<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { headers: this.headers() })),
300	      ]);
301	      if (this.session.sheetId() !== sheet) return;
302	      this.people.set(list);
303	      this.claims.set(claims);
304	      this.rates.set(rates);
305	      this.statements.set(statements);
306	      this.periods.set(periods);
307	    } catch {
308	      if (this.session.sheetId() === sheet) this.error.set('Could not load the people on this sheet.');
309	    }
310	  }
311	
312	  protected claimsOf(personId: number): Claim[] {
313	    return this.claimsByPerson().get(personId) ?? NO_CLAIMS;
314	  }
315	
316	  private claimedCents(personId: number): number {
317	    return this.claimsOf(personId).filter(this.counts).reduce((sum, c) => sum + cents(c.amount), 0);
318	  }
319	
320	  protected claimedOf(personId: number): string {
321	    return money(this.claimedCents(personId));
322	  }
323	
324	  protected ratesOf(grade: string): Rate[] {
325	    return this.ratesByGrade().get(grade) ?? NO_RATES;
326	  }
327	
328	  /** The grade's rate in force on the sheet's today, or null when none is. */
329	  protected pctOf(grade: string): string | null {
330	    return this.pctByGrade().get(grade) ?? null;
331	  }
332	
333	  /**
334	   * The sum of the dues of their claims that count, each already rounded to cents; null (n/a) when
335	   * their grade has no rate in force today and none of those claims has a due fixed when settled or bound by a statement.
336	   */
337	  private dueTotalCents(p: Person): number | null {
338	    const counted = this.claimsOf(p.id).filter(this.counts);
339	    const fixed = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null);
340	    if (this.pctOf(p.grade) === null && !counted.some(fixed)) return null;
341	    const rates = this.ratesOf(p.grade);
342	    const floor = cents(this.session.floor());
343	    const late = this.session.late();
344	    return counted.reduce((sum, c) => sum + (claimDueCents(c, rates, floor, late) ?? 0), 0);
345	  }
346	
347	  protected overdueOf(p: Person): Overdue {
348	    return this.overdueByPerson().get(p.id) ?? { count: 0, cents: 0 };
349	  }
350	
351	  /** Their due-total, or n/a. */
352	  protected dueTotalOf(p: Person): string {
353	    const total = this.dueTotalCents(p);
354	    return total === null ? NA : money(total);
355	  }
356	
357	  protected statementOf(personId: number): StatementSummary | undefined {
358	    return this.statementByPerson().get(personId);
359	  }
360	
361	  /** The last statement's due-total: blank before any statement, n/a when it had none. */
362	  protected statedTotalOf(personId: number): string {
363	    const s = this.statementOf(personId);
364	    return s === undefined ? '' : (s.lastDueTotal ?? NA);
365	  }
366	
367	  /** Take a statement for the person, binding their counting claims to their dues now. */
368	  protected async takeStatement(p: Person): Promise<void> {
369	    this.personError.set(null);
370	    const sheet = this.session.sheetId();
371	    if (!sheet) return;
372	    try {
373	      const taken = await firstValueFrom(
374	        this.http.post<StatementTaken>(`${this.url(sheet)}/${p.id}/statement`, null, { headers: this.headers() }),
375	      );
376	      if (this.session.sheetId() !== sheet) return;
377	      this.statements.update((list) => [...list.filter((s) => s.personId !== p.id), taken.summary]);
378	      const byId = new Map(taken.claims.map((c) => [c.id, c]));
379	      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
380	    } catch {
381	      if (this.session.sheetId() === sheet) this.personError.set({ id: p.id, message: 'Could not take a statement for ' + p.name + '.' });
382	    }
383	  }
384	
385	  protected clearPersonError(id: number): void {
386	    if (this.personError()?.id === id) this.personError.set(null);
387	  }
388	
389	  /** Retire the person from the date (blank: the sheet's today). */
390	  protected async retire(p: Person, date: string): Promise<void> {
391	    this.personError.set(null);
392	    const sheet = this.session.sheetId();
393	    if (!sheet) return;
394	    const from = date.trim();
395	    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
396	      this.personError.set({ id: p.id, message: 'Enter a date, or leave it blank for today.' });
397	      return;
398	    }
399	    try {
400	      const saved = await firstValueFrom(
401	        this.http.post<Person>(`${this.url(sheet)}/${p.id}/retire`, { from: from || null }, { headers: this.headers() }),
402	      );
403	      if (this.session.sheetId() !== sheet) return;
404	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
405	    } catch {
406	      if (this.session.sheetId() === sheet) this.personError.set({ id: p.id, message: 'Could not retire ' + p.name + '.' });
407	    }
408	  }
409	
410	  /** Put the person on hold, or take them off it when held. */
411	  protected async toggleHold(p: Person): Promise<void> {
412	    this.personError.set(null);
413	    const sheet = this.session.sheetId();
414	    if (!sheet) return;
415	    try {
416	      const saved = await firstValueFrom(
417	        this.http.post<Person>(`${this.url(sheet)}/${p.id}/hold`, null, { headers: this.headers() }),
418	      );
419	      if (this.session.sheetId() !== sheet) return;
420	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
421	    } catch {
422	      if (this.session.sheetId() === sheet) {
423	        this.personError.set({ id: p.id, message: 'Could not ' + (p.held ? 'release ' : 'hold ') + p.name + '.' });
424	      }
425	    }
426	  }
427	
428	  /** Put a set rate in place of the grade's old one from the same date. */
429	  protected rateSaved(rate: Rate): void {
430	    this.rates.update((list) => [...list.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
431	  }
432	
433	  /** Put an added period in its place by from-date, or a closed one in its place. */
434	  protected periodSaved(period: Period): void {
435	    this.periods.update((list) =>
436	      [...list.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : 1)),
437	    );
438	  }
439	
440	  /** Put an added claim first, or an edited one in its place. */
441	  protected claimSaved(claim: Claim): void {
442	    this.claims.update((list) =>
443	      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
444	    );
445	  }
446	
447	  private reset(): void {
448	    this.editingId.set(null);
449	    this.form.reset({ name: '', grade: 'A' }, { emitEvent: false });
450	    this.error.set('');
451	  }
452	
453	  protected edit(p: Person): void {
454	    this.personError.set(null);
455	    this.editingId.set(p.id);
456	    this.editingVersion = p.version;
457	    this.form.setValue({ name: p.name, grade: p.grade }, { emitEvent: false });
458	    this.error.set('');
459	  }
460	
461	  protected cancel(): void {
462	    this.reset();
463	  }
464	
465	  protected async save(): Promise<void> {
466	    if (this.saving) return;
467	    this.error.set('');
468	    const sheet = this.session.sheetId();
469	    if (!sheet) return;
470	    const raw = this.form.getRawValue();
471	    const name = raw.name.trim();
472	    const grade = raw.grade;
473	    if (!name) {
474	      this.error.set('Enter a name.');
475	      return;
476	    }
477	    if (!this.grades.includes(grade)) {
478	      this.error.set('Choose a grade.');
479	      return;
480	    }
481	    const id = this.editingId();
482	    this.saving = true;
483	    try {
484	      if (id === null) {
485	        const added = await firstValueFrom(
486	          this.http.post<Person>(this.url(sheet), { name, grade }, { headers: this.headers() }),
487	        );
488	        if (this.session.sheetId() !== sheet) return;
489	        this.people.update((list) => [...list, added]);
490	      } else {
491	        const saved = await firstValueFrom(
492	          this.http.put<Person>(`${this.url(sheet)}/${id}`, { name, grade, version: this.editingVersion }, { headers: this.headers() }),
493	        );
494	        if (this.session.sheetId() !== sheet) return;
495	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
496	      }
497	      this.reset();
498	    } catch (e) {
499	      if (e instanceof HttpErrorResponse && e.status === 412 && id !== null) {
500	        await this.showCurrent(sheet, id);
501	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
502	        this.error.set('That name is already in use on this sheet.');
503	      } else {
504	        this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
505	      }
506	    } finally {
507	      this.saving = false;
508	    }
509	  }
510	
511	  /**
512	   * Add a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person of
513	   * the name; one not on the sheet is added first with grade A. A refusal adds neither.
514	   */
515	  protected async quickAdd(): Promise<void> {
516	    if (this.quickAdding) return;
517	    this.quickError.set('');
518	    const sheet = this.session.sheetId();
519	    if (!sheet) return;
520	    const raw = this.quickForm.getRawValue();
521	    const name = raw.name.trim();
522	    const amount = raw.amount.trim();
523	    if (!name) {
524	      this.quickError.set('Enter a name.');
525	      return;
526	    }
527	    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
528	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
529	      return;
530	    }
531	    this.quickAdding = true;
532	    try {
533	      const done = await firstValueFrom(
534	        this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, { headers: this.headers() }),
535	      );
536	      if (this.session.sheetId() !== sheet) return;
537	      if (done.added) this.people.update((list) => [...list.filter((p) => p.id !== done.person.id), done.person]);
538	      this.claimSaved(done.claim);
539	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
540	    } catch (e) {
541	      if (this.session.sheetId() !== sheet) return;
542	      this.quickError.set(
543	        e instanceof HttpErrorResponse && e.status === 423
544	          ? 'No claim dated inside a closed period can be changed.'
545	          : e instanceof HttpErrorResponse && e.status === 422
546	          ? RETIRED
547	          : e instanceof HttpErrorResponse && e.status === 409
548	          ? 'That name is already in use on this sheet.'
549	          : 'Could not quick-add that claim.',
550	      );
551	    } finally {
552	      this.quickAdding = false;
553	    }
554	  }
555	
556	  /** After a save refused as made from an old version: refuse it, and show the person as now stored. */
557	  private async showCurrent(sheet: string, id: number): Promise<void> {
558	    this.error.set('Someone else saved this person meanwhile; it now shows their values.');
559	    try {
560	      const list = await firstValueFrom(this.http.get<Person[]>(this.url(sheet), { headers: this.headers() }));
561	      if (this.session.sheetId() !== sheet) return;
562	      this.people.set(list);
563	      const current = list.find((p) => p.id === id);
564	      if (current && this.editingId() === id) {
565	        this.editingVersion = current.version;
566	        this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
567	      }
568	    } catch {
569	      // the error already shown stands
570	    }
571	  }
572	}
